import math
mode='rev'
prev_phi=0.0
phi_f=0.0
n=0
def clamp(x,a,b):
    return a if x<a else (b if x>b else x)
def control(obs):
    global mode,prev_phi,phi_f,n
    n+=1
    look=-23
    h=obs.get('hitch_deg',0.0) or 0.0
    st=obs.get('status')
    rig=obs['rig']
    if st=='JACKKNIFED' or abs(h)>50:
        mode='fwd'
    if mode=='fwd':
        if abs(h)<12:
            mode='rev'
        else:
            return (0.0,1.5,look)
    r=rig['trailer_rear']; th=rig['trailer_heading_deg']
    ub=math.radians(th+180.0)
    ux,uy=math.cos(ub),math.sin(ub)
    nx,ny=uy,-ux
    pts=[]
    views=obs.get('views') or {}
    for k,v in views.items():
        if not v: continue
        o=v.get('origin',[0,0])
        for w in v.get('walls',[]) or []:
            b=math.radians(w[0]); d=w[1]
            px=o[0]+d*math.cos(b); py=o[1]+d*math.sin(b)
            dx=px-r[0]; dy=py-r[1]
            pts.append((dx*ux+dy*uy, dx*nx+dy*ny))
    # target aim
    tphi=None
    cam=views.get('camera') if isinstance(views,dict) else None
    corners=[]
    for k,v in views.items():
        if not v: continue
        o=v.get('origin',[0,0])
        for c in v.get('target_corners',[]) or []:
            try:
                b=math.radians(c[0]); d=c[1]
                corners.append((o[0]+d*math.cos(b),o[1]+d*math.sin(b)))
            except Exception:
                pass
    tgt=obs.get('target') or {}
    tp=None
    if len(corners)>=3:
        tp=(sum(c[0] for c in corners)/len(corners),sum(c[1] for c in corners)/len(corners))
    elif tgt.get('in_sight') and tgt.get('bearing_deg') is not None and tgt.get('dist_m') is not None:
        e=rig['eye']; b=math.radians(tgt['bearing_deg']); d=tgt['dist_m']
        tp=(e[0]+d*math.cos(b),e[1]+d*math.sin(b))
    if tp is not None:
        dx=tp[0]-r[0]; dy=tp[1]-r[1]
        a=dx*ux+dy*uy; l=dx*nx+dy*ny
        if a>-0.5 and math.hypot(a,l)<14:
            tphi=math.degrees(math.atan2(l,max(a,0.3)))
    best=None; bs=-1e9
    for i in range(-14,15):
        ph=i*5.0
        c=math.cos(math.radians(ph)); s=math.sin(math.radians(ph))
        free=9.0
        for (a,l) in pts:
            al=a*c+l*s; la=-a*s+l*c
            if al>-0.5 and abs(la)<1.1:
                if al<free: free=al
        sc=free-0.02*abs(ph)-0.015*abs(ph-prev_phi)
        if sc>bs: bs=sc; best=ph
    phi=best if best is not None else 0.0
    prev_phi=phi
    if tphi is not None:
        phi=tphi
    phi_f=0.6*phi_f+0.4*phi
    hd=clamp(0.8*phi_f,-38,38)
    steer=-0.6*hd+3.0*(h-hd)
    steer=clamp(steer,-34,34)
    sp=-1.0
    if abs(h)>40: sp=-0.6
    if n%20==0:
        print('t%.1f h%.1f phi%.0f tphi%s hd%.1f st%.1f np%d'%(obs.get('t',0),h,phi,tphi if tphi is None else round(tphi),hd,steer,len(pts)))
    return (steer,sp,look)

