import math
L=2.5;A=1.3;L2=3.6
X=0.0;Y=0.0;H=0.0
mem={}
phase='REV'
n=0

def clamp(v,a,b):
    return max(a,min(b,v))

def wrap(a):
    while a>180: a-=360
    while a<-180: a+=360
    return a

def control(obs):
    global X,Y,H,phase,n
    n+=1
    dt=obs.get('dt',0.1) or 0.1
    m=obs['motion']; v=m['v_mps']; st=math.radians(obs['steer_deg'])
    H+=v*math.tan(st)/L*dt; X+=v*math.cos(H)*dt; Y+=v*math.sin(H)*dt
    c=math.cos(H); s=math.sin(H)
    views=obs.get('views') or {}
    for name,vw in views.items():
        if not vw: continue
        ox,oy=vw['origin']
        for b,d in vw.get('walls',[]) or []:
            br=math.radians(b)
            px=ox+d*math.cos(br); py=oy+d*math.sin(br)
            wx=X+px*c-py*s; wy=Y+px*s+py*c
            mem[(round(wx/0.3),round(wy/0.3))]=(wx,wy)
    phi=obs['hitch_deg']
    rig=obs['rig']; rx,ry=rig['trailer_rear']; th=rig['trailer_heading_deg']
    base=th+180.0
    pts=[]
    for wx,wy in mem.values():
        dx=wx-X; dy=wy-Y
        px=dx*c+dy*s; py=-dx*s+dy*c
        if (px-rx)**2+(py-ry)**2<225: pts.append((px-rx,py-ry))
    best=None; dsel=0; bh=0
    for d in range(-60,61,5):
        a=math.radians(base+d); ux=math.cos(a); uy=math.sin(a)
        hit=12.0
        ll=[]
        for qx,qy in pts:
            lon=qx*ux+qy*uy; lat=-qx*uy+qy*ux
            ll.append((lon,lat))
            if 0<lon<hit and abs(lat)<1.5: hit=lon
        marg=3.0
        lim=min(hit,8.0)
        for lon,lat in ll:
            if -1.5<lon<lim:
                if abs(lat)<marg: marg=abs(lat)
        sc=hit+1.5*marg-0.02*abs(d)
        if best is None or sc>best:
            best=sc; dsel=d; bh=hit
    tg=obs.get('target') or {}
    near=False
    if tg.get('in_sight') and tg.get('dist_m') is not None and tg.get('bearing_deg') is not None:
        tb=math.radians(tg['bearing_deg']); td=tg['dist_m']
        tx=0.75+td*math.cos(tb); ty=td*math.sin(tb)
        dr=math.hypot(tx-rx,ty-ry)
        if dr<7: near=True
        dt_=wrap(math.degrees(math.atan2(ty-ry,tx-rx))-base)
        if dr<12 and abs(dt_)<60:
            dsel=dt_
    if phase=='REV' and abs(phi)>58: phase='FWD'
    if phase=='FWD':
        if abs(phi)<12: phase='REV'
        else:
            return (0.0,1.0,170)
    phid=clamp(0.9*dsel,-35,35)
    pr=math.radians(phid)
    ff=math.degrees(math.atan(L*math.sin(pr)/(L2+A*math.cos(pr))))
    steer=clamp(ff+2.5*(phi-phid),-45,45)
    spd=-0.6 if near else -1.0
    if n%20==0:
        print('t%.0f phi%.0f d%.0f hit%.1f np%d st%.0f near%s'%(obs['t'],phi,dsel,bh,len(pts),steer,near))
    return (steer,spd,170)

