            lon=qx*ux+qy*uy; lat=-qx*uy+qy*ux
            ll.append((lon,lat))
            if 0<lon<hit and abs(lat)<1.7: hit=lon
        marg=3.5
        lim=min(hit,8.0)
        for lon,lat in ll:
            if -1.0<lon<lim and abs(lat)<marg: marg=abs(lat)
        sc=hit+2.0*marg-0.03*abs(d)
        if best is None or sc>best:
            best=sc; dsel=d; bh=hit
    tg=obs.get('target') or {}
    near=False
    if tg.get('in_sight') and tg.get('dist_m') is not None and tg.get('bearing_deg') is not None:
        tb=math.radians(tg['bearing_deg']); td=tg['dist_m']
        tx=0.75+td*math.cos(tb); ty=td*math.sin(tb)
        dr=math.hypot(tx-rx,ty-ry)
        if dr<7: near=True
        dt_=wrap(math.degrees(math.atan2(ty-ry,tx-rx))-base)
        if dr<12 and abs(dt_)<60:
            dsel=dt_
    phid=clamp(0.9*dsel,-38,38)
    pr=math.radians(phid)
