import math
L1=1.25;C=0.3;L2=0.85
X=0.0;Y=0.0;th=0.0;last_t=None;Yc=None;bay=None;mode='rev';logt=-10
LW=[];RW=[]
def cl(a,lo,hi):
    return max(lo,min(hi,a))
def wrap(a):
    while a>math.pi:a-=2*math.pi
    while a<-math.pi:a+=2*math.pi
    return a
def tow(px,py):
    c=math.cos(th);s=math.sin(th)
    return (X+c*px-s*py, Y+s*px+c*py)
def control(obs):
    global X,Y,th,last_t,Yc,bay,mode,logt,LW,RW
    t=obs['t']
    v=obs['motion']['v_mps'];st=math.radians(obs['steer_deg'])
    if last_t is not None:
        d=t-last_t
        X+=v*math.cos(th)*d;Y+=v*math.sin(th)*d;th+=v*math.tan(st)/L1*d
    last_t=t
    phi=obs['hitch_deg']
    rig=obs['rig']
    tht=th-math.radians(phi)
    hx,hy=rig['hitch']
    HX,HY=tow(hx,hy)
    AX=HX-L2*math.cos(tht);AY=HY-L2*math.sin(tht)
    if Yc is None: Yc=0.0
    lefts=[];rights=[]
    try:
        for name,vw in (obs.get('views') or {}).items():
            if not vw: continue
            ox,oy=vw['origin']
            for b,dd in vw.get('walls',[]):
                br=math.radians(b)
                wx,wy=tow(ox+dd*math.cos(br),oy+dd*math.sin(br))
                if AX-6.0<wx<AX+0.8:
                    if wy>Yc+0.5: lefts.append(wy)
                    elif wy<Yc-0.5: rights.append(wy)
    except Exception as e:
        pass
    if lefts and rights:
        lefts.sort();rights.sort()
        lm=lefts[len(lefts)//2];rm=rights[len(rights)//2]
        if 1.5<lm-rm<8:
            est=(lm+rm)/2
            if bay is None: Yc+=0.08*(est-Yc)
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('bearing_deg') is not None:
        ex,ey=rig['eye'];br=math.radians(tg['bearing_deg']);dd=tg['dist_m']
        bx,by=tow(ex+dd*math.cos(br),ey+dd*math.sin(br))
        if bay is None: bay=[bx,by]
        else:
            bay[0]+=0.1*(bx-bay[0]);bay[1]+=0.1*(by-bay[1])
        Yc+=0.15*(bay[1]-Yc)
    rem=obs['progress']['remaining']
    if mode=='rev' and abs(phi)>38: mode='fwd'
    if mode=='fwd' and abs(phi)<6: mode='rev'
    if mode=='fwd':
        steer=0.0;spd=0.6
    else:
        e=AY-Yc
        thd=cl(0.5*e,-0.35,0.35)
        if rem<1.5: thd=cl(thd,-0.1,0.1)
        phid=cl(math.degrees(2.0*wrap(tht-thd)),-25,25)
        steer=cl(1.087*phid+3.0*(phi-phid),-45,45)
