import math
L=3.9; A=0.35; LT=10.2
S={'stopped':False,'woke':False}
def clamp(v,lo,hi): return max(lo,min(hi,v))
def control(obs):
    phi=obs['hitch_deg']
    rig=obs['rig']
    look=rig.get('screen_gaze_deg')
    if look is None: look=-72
    pr=math.radians(phi)
    deq=math.degrees(math.atan(L*math.sin(pr)/(LT-A*math.cos(pr))))
    steer=clamp(deq+1.5*phi,-30,30)
    views=obs.get('views') or {}
    cam=views.get('camera')
    if cam:
        th=rig['trailer_heading_deg']
        back=th+180
        for b,d in (cam.get('walls') or []):
            rel=(b-back+540)%360-180
            if abs(rel)<20 and d*math.cos(math.radians(rel))<1.3:
                S['stopped']=True
    if S['stopped']:
        if not S['woke']:
            S['woke']=True
            try: wake('final: wall close behind, stopped, hitch %.1f'%phi)
            except Exception: pass
        return {'steer_deg':steer,'speed_mps':0,'look_deg':look}
    return {'steer_deg':steer,'speed_mps':-0.5,'look_deg':look}

